#include <vector>

class Solution {
public:
    std::vector<int> multiply(std::vector<int>& poly1, std::vector<int>& poly2) {
        int n1 = poly1.size(), n2 = poly2.size();
        std::vector<int> res(n1 + n2 - 1, 0);
        for (int i = 0; i < n1; ++i) {
            for (int j = 0; j < n2; ++j) {
                res[i + j] += poly1[i] * poly2[j];
            }
        }
        return res;
    }
};

class Solution {
    public int[] multiply(int[] poly1, int[] poly2) {
        int n1 = poly1.length, n2 = poly2.length;
        int[] res = new int[n1 + n2 - 1];
        for (int i = 0; i < n1; ++i) {
            for (int j = 0; j < n2; ++j) {
                res[i + j] += poly1[i] * poly2[j];
            }
        }
        return res;
    }
}

/**
 * @param {number[]} poly1
 * @param {number[]} poly2
 * @return {number[]}
 */
var multiply = function(poly1, poly2) {
    const n1 = poly1.length, n2 = poly2.length;
    const res = new Array(n1 + n2 - 1).fill(0);
    for (let i = 0; i < n1; ++i) {
        for (let j = 0; j < n2; ++j) {
            res[i + j] += poly1[i] * poly2[j];
        }
    }
    return res;
};
